function alcoholG(volMl, abv){ return volMl*abv*0.789; } // 乙醇密度 0.789 g/mL
function bac(sex, kg, volMl, abv, tHours){
  var r = sex==='f' ? 0.55 : 0.68; // 威德马克分布系数
  var A = alcoholG(volMl, abv);
  return A/(10*r*kg) - 0.015*tHours; // g/100mL(%), 代谢 0.015/h
}
function soberHours(sex, kg, volMl, abv, tHours){
  var b=bac(sex,kg,volMl,abv,tHours); return b>0 ? b/0.015 : 0;
}
var EXPORTS={alcoholG:alcoholG, bac:bac, soberHours:soberHours};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BacForgePure = EXPORTS; }
